// Villager trade pools for Minecraft Java Edition 1.21.x (1.21.5+ cartographer trades) and current Bedrock Edition.
// Source: Minecraft Wiki (https://minecraft.wiki/w/Trading and the per-profession pages), read 2026-10-23.
// Default trades only; the "Villager Trade Rebalance" experiment is ignored.

export type Edition = "java" | "bedrock";

export type TradeCategory =
  | "enchanted-book"
  | "armor"
  | "weapon"
  | "tool"
  | "food"
  | "building"
  | "brewing"      // cleric/magic items: redstone, lapis, glowstone, ender pearl, bottle o' enchanting, etc.
  | "maps-banners" // explorer maps, banners, banner patterns, item frames
  | "decoration"   // flowers, dyes, beds, carpets, paintings, terracotta, etc.
  | "emerald-income" // every "buy" trade (villager gives emeralds) goes here regardless of item
  | "misc";

export interface TradeDef {
  /** snake_case, unique within (profession, edition). Use the SAME id for the same trade across editions. Sell trades: the item id, e.g. "iron_chestplate". Buy trades: "buy_" + item id, e.g. "buy_coal". */
  id: string;
  /** one of: armorer butcher cartographer cleric farmer fisherman fletcher leatherworker librarian mason shepherd toolsmith weaponsmith */
  profession: string;
  /** 1 Novice, 2 Apprentice, 3 Journeyman, 4 Expert, 5 Master */
  level: 1 | 2 | 3 | 4 | 5;
  /** "sell": villager gives the item for emeralds. "buy": villager gives emeralds for the item. */
  kind: "sell" | "buy";
  /** Display name of the item the trade is about, e.g. "Iron Chestplate", "Coal", "Woodland Explorer Map". */
  item: string;
  /** How many of the item change hands in one trade (e.g. buy 15 coal → count 15; sell 4 bread → count 4). */
  count: number;
  /** Base emerald cost for sell trades, or emeralds received for buy trades, as [min, max] (same number twice if fixed). For randomly enchanted items use the wiki's range. */
  emeralds: [number, number];
  /** Any additional input besides emeralds, e.g. "1 Book", "1 Compass", "6 Raw Cod", "1 Glass Bottle"... omit if none. */
  extra?: string;
  /** true if the item comes with random enchantments. */
  enchanted?: boolean;
  category: TradeCategory;
  /** Short helpful note, optional, e.g. "Random dye colour" or "Bedrock: biome-dependent". Keep under ~60 chars. */
  note?: string;
}

export interface EnchantDef {
  id: string;        // e.g. "mending", "protection", "curse_of_vanishing"
  name: string;      // e.g. "Mending", "Protection", "Curse of Vanishing"
  maxLevel: number;
  /** treasure enchantments cost double from librarians (Mending, Frost Walker, curses...) */
  treasure: boolean;
  /** what it goes on, one of: "armor" | "helmet" | "chestplate" | "leggings" | "boots" | "sword" | "axe" | "tool" | "bow" | "crossbow" | "trident" | "fishing_rod" | "mace" | "universal" */
  appliesTo: string;
}

